<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onPullDownRefresh, onShow } from '@dcloudio/uni-app'
import { distributionApi } from '../../api/distribution.api'
import { qualityApi } from '@/features/quality/api/quality.api'
import QualityMarkDrawer from '@/features/quality/components/QualityMarkDrawer.vue'
import type { DistributionItem, DistributionShelfDetail } from '../../models/distribution'
import WareState from '@/shared/components/WareState.vue'

const date=ref(''),shelfNo=ref(''),detail=ref<DistributionShelfDetail>(),activeId=ref(0),selected=ref<number[]>([]),filter=ref<'all'|'pending'|'allocated'|'problem'>('all'),loading=ref(true),saving=ref(false),loaded=ref(false),markVisible=ref(false)
const item=computed(()=>detail.value?.items.find(value=>value.id===activeId.value))
const problemMap=computed(()=>new Map((item.value?.problemMarks||[]).map(value=>[value.unit,value])))
const selectedProblemCount=computed(()=>selected.value.filter(unit=>problemMap.value.has(unit)).length)
const units=computed(()=>Array.from({length:item.value?.totalUnits||0},(_,index)=>index+1).filter(unit=>filter.value==='allocated'?item.value?.allocatedUnits.includes(unit):filter.value==='pending'?!item.value?.allocatedUnits.includes(unit):filter.value==='problem'?problemMap.value.has(unit):true))
const totalUnits=computed(()=>detail.value?.items.reduce((sum,value)=>sum+value.totalUnits,0)||0)
const allocatedUnits=computed(()=>detail.value?.items.reduce((sum,value)=>sum+value.allocatedUnits.length,0)||0)
const customers=computed(()=>{const result:{name:string;phone:string}[]=[];for(const value of detail.value?.items||[]){if(value.customerName&&!result.some(customer=>customer.name===value.customerName&&customer.phone===value.customerPhone))result.push({name:value.customerName,phone:value.customerPhone})}return result})
function rankLabel(rank:number){return `${String.fromCharCode(64+Math.max(1,rank))}级`}
async function load(){loading.value=true;try{detail.value=await distributionApi.shelf(date.value,shelfNo.value);if(activeId.value&&!detail.value.items.some(value=>value.id===activeId.value))activeId.value=0}catch(e){uni.showToast({title:e instanceof Error?e.message:'加载失败',icon:'none'})}finally{loading.value=false;uni.stopPullDownRefresh()}}
function toggleItem(value:DistributionItem){activeId.value=activeId.value===value.id?0:value.id;selected.value=[];filter.value='all'}
function toggleUnit(unit:number){selected.value=selected.value.includes(unit)?selected.value.filter(value=>value!==unit):[...selected.value,unit]}
function selectPending(){if(!item.value)return;selected.value=Array.from({length:item.value.totalUnits},(_,index)=>index+1).filter(value=>!item.value!.allocatedUnits.includes(value)&&!problemMap.value.has(value))}
function callPhone(phone:string){if(!phone)return uni.showToast({title:'未留联系电话',icon:'none'});uni.makePhoneCall({phoneNumber:phone})}
async function submit(allocated:boolean){if(!item.value||!selected.value.length)return uni.showToast({title:'请先选择花材',icon:'none'});const current=item.value;uni.showModal({title:allocated?'确认配货':'确认取消配货',content:`${current.supplierName} · ${current.productName}，将对已选 ${selected.value.length} 扎执行${allocated?'配货':'取消配货'}，是否继续？`,confirmColor:allocated?'#0F766E':'#C93636',success:async({confirm})=>{if(!confirm)return;saving.value=true;try{await distributionApi.allocation(current.id,selected.value,allocated);selected.value=[];await load();uni.showToast({title:allocated?'配货成功':'已取消配货',icon:'success'})}finally{saving.value=false}}})}
function openQualityMark(){if(!item.value||!selected.value.length)return uni.showToast({title:'请先选择需要标记的花材',icon:'none'});markVisible.value=true}
async function qualityMarkSuccess(){markVisible.value=false;selected.value=[];await load()}
function revokeQualityMark(){if(!item.value||!selectedProblemCount.value)return uni.showToast({title:'所选花材没有可撤销的质检标记',icon:'none'});const current=item.value;const units=selected.value.filter(unit=>problemMap.value.has(unit));uni.showModal({title:'撤销质检标记',content:`将撤销 ${current.productName} 已选中的 ${units.length} 扎缺货/退货质检标记。配货状态不会改变，是否继续？`,confirmText:'确认撤销',confirmColor:'#C93636',success:async({confirm})=>{if(!confirm)return;saving.value=true;try{await qualityApi.revokeInspection(current.id,units);selected.value=[];await load();uni.showToast({title:'质检标记已撤销',icon:'success'})}catch(e){uni.showToast({title:e instanceof Error?e.message:'撤销失败',icon:'none'})}finally{saving.value=false}}})}
onLoad(query=>{date.value=String(query?.date||new Date().toISOString().slice(0,10));shelfNo.value=decodeURIComponent(String(query?.shelf||''));load().finally(()=>loaded.value=true)});onShow(()=>{if(loaded.value)load()});onPullDownRefresh(load)
</script>

<template><view class="page">
  <view class="head"><view class="shelf-info"><text class="title">#{{shelfNo}}段</text><view v-if="customers.length" class="customer-lines"><text v-for="customer in customers" :key="customer.name+customer.phone" @click="callPhone(customer.phone)">{{customer.name}} · {{customer.phone}}</text></view></view><view class="summary"><strong>{{allocatedUnits}}/{{totalUnits}}</strong><text>已配货/总数</text></view></view>
  <WareState v-if="loading" type="loading" title="正在加载订单商品"/>
  <template v-else-if="detail">
    <view class="list-head"><text>货架商品明细</text><text>共 {{detail.items.length}} 项 · 按订单拆分</text></view>
    <view class="goods-list"><view v-for="entry in detail.items" :key="entry.id" :class="['goods-card',{expanded:activeId===entry.id}]">
      <view class="goods-main" @click="toggleItem(entry)">
        <view class="goods-top"><view class="supplier-row"><text v-if="entry.baseShortName" class="supplier-badge">{{entry.baseShortName}}</text><strong>{{entry.supplierName}}</strong><text v-if="entry.limitDistribution" class="limit">限制自主配货</text></view><view class="progress-count"><strong>{{entry.allocatedUnits.length}}</strong>/{{entry.totalUnits}}</view></view>
        <view class="goods-body"><view class="goods-info"><text class="product">{{entry.productName}} · {{rankLabel(entry.rank)}} <b>¥{{entry.supplyPrice.toFixed(2)}}</b></text><text class="sku">{{entry.skuConfig}}</text><text v-if="entry.customerName" class="customer">{{entry.customerName}}</text></view><text class="expand">{{activeId===entry.id?'收起':'展开'}}</text></view>
        <view class="exception-row"><text v-if="entry.problemMarks.length" class="danger">问题 {{entry.problemMarks.length}}</text><text v-if="entry.exceptions.shortage">缺 {{entry.exceptions.shortage}}</text><text v-if="entry.exceptions.shortageRestock">缺补 {{entry.exceptions.shortageRestock}}</text><text v-if="entry.exceptions.return">退 {{entry.exceptions.return}}</text><text v-if="entry.exceptions.returnRestock">退补 {{entry.exceptions.returnRestock}}</text><text v-if="entry.exceptions.downgrade">降 {{entry.exceptions.downgrade}}</text><text v-if="entry.exceptions.restock">待补 {{entry.exceptions.restock}}</text></view>
      </view>
      <view v-if="activeId===entry.id" class="expanded-content">
        <view class="selection-note"><strong>{{entry.supplierName}} · {{entry.productName}}</strong><text>当前仅操作这一条订单商品，其他条目不受影响</text></view>
        <view class="tools"><view class="filters"><text v-for="option in [{v:'all',l:'全部'},{v:'pending',l:'待配'},{v:'allocated',l:'已配'},{v:'problem',l:'问题'}]" :key="option.v" :class="{active:filter===option.v}" @click="filter=option.v as any">{{option.l}}</text></view><text class="quick" @click="selectPending">全选可配</text><text v-if="selected.length" class="clear" @click="selected=[]">清空</text></view>
        <view class="unit-grid"><view v-for="unit in units" :key="unit" :class="['unit',{selected:selected.includes(unit),allocated:entry.allocatedUnits.includes(unit),problem:problemMap.has(unit)}]" @click="toggleUnit(unit)"><text v-if="selected.includes(unit)" class="check">✓</text><strong>{{String(unit).padStart(4,'0')}}</strong><text>{{problemMap.get(unit)?.label||(entry.allocatedUnits.includes(unit)?'已配货':'待配货')}}</text></view></view>
      </view>
    </view></view>
    <view class="safe-space"/>
    <QualityMarkDrawer v-if="item" :visible="markVisible" :item-id="item.id" :units="selected" :product-name="`${item.productName} · ${rankLabel(item.rank)}`" :supplier-name="item.supplierName" @close="markVisible=false" @success="qualityMarkSuccess"/>
    <view v-if="item" class="bottom"><view class="selection"><text>已选</text><strong>{{selected.length}}</strong><text>扎</text></view><view class="action-stack"><view class="quality-actions"><button class="quality-mark" :disabled="saving||!selected.length" @click="openQualityMark">缺货/退货标记</button><button class="revoke-mark" :disabled="saving||!selectedProblemCount" @click="revokeQualityMark">撤销标记</button></view><view class="allocation-actions"><button class="cancel" :disabled="saving||!selected.length" @click="submit(false)">取消配货</button><button :disabled="saving||!selected.length" @click="submit(true)">确认配货</button></view></view></view>
  </template>
</view></template>

<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx}.head{display:flex;align-items:flex-end;justify-content:space-between}.eyebrow,.title{display:block}.eyebrow{color:var(--wms-text-secondary);font-size:22rpx}.title{margin-top:4rpx;font-size:42rpx;font-weight:850}.summary{text-align:right}.summary strong,.summary text{display:block}.summary strong{font-size:31rpx}.summary text{margin-top:3rpx;color:var(--wms-text-secondary);font-size:19rpx}.list-head{display:flex;justify-content:space-between;margin:26rpx 2rpx 12rpx}.list-head>text:first-child{font-size:28rpx;font-weight:800}.list-head>text:last-child{color:var(--wms-text-secondary);font-size:20rpx}.goods-list{display:flex;gap:16rpx;flex-direction:column}.goods-card{overflow:hidden;border:2rpx solid transparent;border-radius:22rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.goods-card.expanded{border-color:rgba(15,118,110,.42)}.goods-main{padding:21rpx}.goods-top,.goods-body{display:flex;align-items:flex-start;justify-content:space-between}.order-identity{display:flex;align-items:center;gap:8rpx;color:var(--wms-text-secondary);font-size:18rpx}.order-tag{padding:5rpx 8rpx;border-radius:7rpx;background:#e5f2ef;color:var(--wms-primary-700);font-weight:750}.progress-count{color:var(--wms-text-secondary);font-size:23rpx}.progress-count strong{color:var(--wms-primary-700);font-size:31rpx}.goods-body{margin-top:13rpx}.goods-info{min-width:0;flex:1}.supplier-row{display:flex;align-items:center;gap:8rpx}.supplier-row strong{overflow:hidden;font-size:25rpx;white-space:nowrap;text-overflow:ellipsis}.supplier-badge{display:flex;width:31rpx;height:31rpx;align-items:center;justify-content:center;border-radius:7rpx;background:#687b78;color:#fff;font-size:18rpx}.limit{padding:4rpx 7rpx;border-radius:6rpx;background:#fff0ee;color:#bd3c28;font-size:16rpx}.product,.sku,.order-no{display:block;margin-top:8rpx}.product{font-size:25rpx;font-weight:700}.product b{margin-left:7rpx;color:#13805a;font-size:21rpx}.sku,.order-no{color:var(--wms-text-secondary);font-size:19rpx}.order-no{opacity:.82}.expand{align-self:center;margin-left:14rpx;color:var(--wms-primary-700);font-size:21rpx}.exception-row{display:flex;gap:8rpx;margin-top:13rpx;flex-wrap:wrap}.exception-row text{padding:5rpx 8rpx;border-radius:7rpx;background:#fff3df;color:#985400;font-size:17rpx}.exception-row .danger{background:#fff0ee;color:#bd3c28}.expanded-content{padding:0 18rpx 20rpx;border-top:1rpx solid var(--wms-border);background:#fbfdfc}.selection-note{display:flex;align-items:center;gap:8rpx;padding:15rpx 2rpx;color:var(--wms-text-secondary);font-size:18rpx;flex-wrap:wrap}.selection-note strong{color:var(--wms-primary-700)}.selection-note text:last-child{width:100%}.tools{display:flex;align-items:center}.filters{display:flex;min-width:0;flex:1;gap:8rpx}.filters text,.quick,.clear{padding:9rpx 13rpx;border-radius:999rpx;background:#e6edeb;color:var(--wms-text-secondary);font-size:19rpx}.filters .active{background:var(--wms-primary-700);color:#fff}.quick{margin-left:6rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700)}.clear{margin-left:5rpx;background:#fff0f0;color:var(--wms-danger)}.unit-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10rpx;margin-top:15rpx}.unit{position:relative;display:flex;min-height:82rpx;align-items:center;justify-content:center;border:2rpx solid transparent;border-radius:11rpx;background:#e8edec;flex-direction:column}.unit strong{font-size:20rpx}.unit>text:last-child{margin-top:3rpx;color:var(--wms-text-secondary);font-size:14rpx}.unit.allocated{background:#dff2ed;color:var(--wms-primary-700)}.unit.problem{background:#fff0eb;color:#bd3c28}.unit.selected{border-color:var(--wms-primary-700);box-shadow:0 0 0 2rpx rgba(15,118,110,.12)}.check{position:absolute;top:3rpx;right:5rpx;color:var(--wms-primary-700);font-size:16rpx}.safe-space{height:150rpx}.bottom{position:fixed;right:0;bottom:0;left:0;display:flex;align-items:center;gap:12rpx;padding:18rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));border-top:1rpx solid var(--wms-border);background:#fff}.selection{min-width:92rpx;color:var(--wms-text-secondary);font-size:19rpx}.selection strong{margin:0 4rpx;color:var(--wms-primary-700);font-size:30rpx}.bottom button{height:74rpx;margin:0;border:0;border-radius:16rpx;background:var(--wms-primary-700);color:#fff;font-size:23rpx;font-weight:750;line-height:74rpx}.bottom .cancel{background:var(--wms-surface-soft);color:var(--wms-primary-700)}.bottom button[disabled]{opacity:.42}
.head{align-items:flex-start}.shelf-info{min-width:0;flex:1}.title{margin-top:0}.customer-lines{display:flex;gap:5rpx;margin-top:7rpx;flex-direction:column}.customer-lines text{color:var(--wms-primary-700);font-size:20rpx}.summary{flex:none;padding-top:5rpx}.list-head{align-items:center;line-height:1}.supplier-row{min-width:0}.supplier-badge{width:auto;min-width:46rpx;padding:0 7rpx;white-space:nowrap}.product,.sku,.customer{display:block;margin-top:8rpx}.customer{color:#7b8885;font-size:19rpx}.selection-note strong{color:var(--wms-text)}
.safe-space{height:230rpx}.bottom{gap:14rpx;padding-top:14rpx;padding-bottom:calc(14rpx + env(safe-area-inset-bottom))}.action-stack{display:flex;min-width:0;flex:1;gap:10rpx;flex-direction:column}.quality-actions,.allocation-actions{display:grid;grid-template-columns:1fr 1fr;gap:10rpx}.bottom button{height:64rpx;padding:0 8rpx;border-radius:14rpx;font-size:21rpx;line-height:64rpx}.bottom .quality-mark{background:#fff0ee;color:var(--wms-danger)}.bottom .revoke-mark{box-shadow:inset 0 0 0 1rpx var(--wms-border);background:#fff;color:var(--wms-text-secondary)}.bottom button:after{border:0}
</style>
